import sys, openpyxl
from openpyxl.utils import get_column_letter
for path in sys.argv[1:]:
    print("=================== ", path)
    wb = openpyxl.load_workbook(path, data_only=False)
    try:
        wbv = openpyxl.load_workbook(path, data_only=True)
    except Exception as e:
        wbv = None
    print("Sheets:", [(ws.title, ws.sheet_state) for ws in wb.worksheets])
    if wb.defined_names:
        try:
            for n in wb.defined_names:
                print("DefinedName:", n, wb.defined_names[n].attr_text)
        except Exception as e:
            print("defined names err", e)
    for ws in wb.worksheets:
        print(f"--- Sheet: {ws.title} (state={ws.sheet_state}) dims={ws.dimensions} max_row={ws.max_row} max_col={ws.max_column}")
        hidden_rows = [r for r, d in ws.row_dimensions.items() if d.hidden]
        hidden_cols = [c for c, d in ws.column_dimensions.items() if d.hidden]
        if hidden_rows: print("  HIDDEN ROWS:", hidden_rows)
        if hidden_cols: print("  HIDDEN COLS:", hidden_cols)
        if ws.merged_cells.ranges: print("  merged:", [str(r) for r in ws.merged_cells.ranges][:30])
        wsv = wbv[ws.title] if wbv else None
        for row in ws.iter_rows():
            vals = []
            for c in row:
                if c.value is None: continue
                v = c.value
                s = f"{c.coordinate}={v!r}"
                if isinstance(v, str) and v.startswith("="):
                    if wsv is not None:
                        s += f" [val={wsv[c.coordinate].value!r}]"
                if c.comment:
                    s += f" [COMMENT: {c.comment.text!r}]"
                if c.font and c.font.strike:
                    s += " [STRIKE]"
                if c.fill and c.fill.fgColor and c.fill.fgColor.rgb not in (None, '00000000') and c.fill.fill_type:
                    s += f" [fill={c.fill.fgColor.rgb}]"
                vals.append(s)
            if vals:
                print("  " + " | ".join(vals))
        # data validations
        if ws.data_validations and ws.data_validations.dataValidation:
            for dv in ws.data_validations.dataValidation:
                print("  DV:", dv.sqref, dv.formula1)
EOF
